# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="24" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">BESİN GRUPLARININ OKSİJENLİ SOLUNUMA KATILIM YOLLARI</text>\n  <rect x="20" y="40" width="205" height="62" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="122" y="60" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">KARBOHİDRATLAR (Polisakkarit)</text>\n  <text x="122" y="78" text-anchor="middle" font-size="10.5" fill="#1e3a8a">Sindirim → Monosakkarit (Glikoz)</text>\n  <text x="122" y="94" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">Doğrudan Glikolizden Katılır</text>\n  <rect x="247" y="40" width="205" height="62" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="350" y="60" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">LİPİTLER (Nötral Yağ / Trigliserit)</text>\n  <text x="350" y="78" text-anchor="middle" font-size="10.5" fill="#78350f">Gliserol → Glikoliz ara basamağı</text>\n  <text x="350" y="94" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">Yağ Asidi → Beta Oksidasyon → Asetil-KoA</text>\n  <rect x="475" y="40" width="205" height="62" rx="8" fill="#fce7f3" stroke="#db2777" stroke-width="2"/>\n  <text x="577" y="60" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#9d174d">PROTEİNLER (Polipeptit)</text>\n  <text x="577" y="78" text-anchor="middle" font-size="10.5" fill="#831843">Amino Asit → Deaminasyon (-NH3)</text>\n  <text x="577" y="94" text-anchor="middle" font-size="10" font-weight="bold" fill="#be185d">Pirüvat / Asetil-KoA / Krebs Döngüsü</text>\n  <rect x="45" y="122" width="130" height="44" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="2"/>\n  <text x="110" y="142" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e3a8a">1. GLİKOLİZ</text>\n  <text x="110" y="158" text-anchor="middle" font-size="10" fill="#1e40af">(Glikoz → 2 Pirüvat)</text>\n  <line x1="175" y1="144" x2="215" y2="144" stroke="#475569" stroke-width="2"/>\n  <rect x="215" y="122" width="135" height="44" rx="8" fill="#fef9c3" stroke="#ca8a04" stroke-width="2"/>\n  <text x="282" y="142" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#854d0e">2. ASETİL-KoA (2C)</text>\n  <text x="282" y="158" text-anchor="middle" font-size="10" fill="#713f12">(Pirüvat Oksidasyonu)</text>\n  <line x1="350" y1="144" x2="390" y2="144" stroke="#475569" stroke-width="2"/>\n  <rect x="390" y="122" width="135" height="44" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="457" y="142" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">3. SİTRİK ASİT</text>\n  <text x="457" y="158" text-anchor="middle" font-size="10" fill="#14532d">(Krebs Döngüsü)</text>\n  <line x1="525" y1="144" x2="560" y2="144" stroke="#475569" stroke-width="2"/>\n  <rect x="560" y="122" width="110" height="44" rx="8" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="615" y="142" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6b21a8">4. ETS VE ATP</text>\n  <text x="615" y="158" text-anchor="middle" font-size="10" fill="#581c87">(O2 → H2O + ATP)</text>\n  <rect x="20" y="182" width="660" height="66" rx="8" fill="#f1f5f9" stroke="#94a3b8" stroke-width="1.5"/>\n  <text x="350" y="202" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#0f172a">ÖNEMLİ KARŞILAŞTIRMA İLKELERİ (BİY.10.1.7 &amp; BİY.10.1.8)</text>\n  <text x="35" y="221" font-size="10.8" fill="#334155">• Yağ asitleri 2 karbonlu birimlere ayrılarak doğrudan Asetil-KoA basamağından katılır; glikoliz evresine uğramaz.</text>\n  <text x="35" y="238" font-size="10.8" fill="#334155">• Amino asitler solunuma katılmadan önce deaminasyonla amino (-NH2) grubunu bırakır; bu nedenle amonyak (NH3) oluşur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">ENERJİ VERİMİ VE KULLANIM SIRASI KARŞILAŞTIRMASI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1 GRAM BESİNİN ENERJİ VERİM SIRASI</text>\n  <text x="35" y="90" font-size="11.2" font-weight="bold" fill="#1e3a8a">Yağ (9,2 kcal) &gt; Protein (4,3 kcal) &gt; Karbohidrat (4,2 kcal)</text>\n  <text x="35" y="114" font-size="11" fill="#1e3a8a">• Yağların hidrojen/oksijen oranı çok yüksektir.</text>\n  <text x="35" y="136" font-size="11" fill="#1e3a8a">• ETS\'ye daha fazla hidrojen (NADH, FADH2) taşınır.</text>\n  <text x="35" y="158" font-size="11" fill="#1e3a8a">• Bol ATP ve bol metabolik su (H2O) açığa çıkar.</text>\n  <text x="35" y="180" font-size="11" fill="#1e3a8a">• Ancak yıkımı için daha fazla oksijen (O2) gerekir.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#065f46">AÇLIKTA HÜCRESEL KULLANIM SIRASI</text>\n  <text x="370" y="90" font-size="11.2" font-weight="bold" fill="#064e3b">1. Karbohidratlar  →  2. Lipitler  →  3. Proteinler</text>\n  <text x="370" y="114" font-size="11" fill="#064e3b">• Karbohidratların yıkımı kolaydır, az O2 harcanır.</text>\n  <text x="370" y="136" font-size="11" fill="#064e3b">• Sinir hücreleri enerji için öncelikle glikoz kullanır.</text>\n  <text x="370" y="158" font-size="11" fill="#064e3b">• Lipitler ikinci sırada, temel enerji deposu olarak yıkılır.</text>\n  <text x="370" y="180" font-size="11" fill="#064e3b">• Proteinler yapısal ve enzimatik olduğundan en son yıkılır.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Çöl hayvanları (deve) ve göçmen kuşlar hem yüksek ATP hem de bol metabolik su için yağ depolar.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">OKSİJENLİ SOLUNUM İLE FERMANTASYONUN KARŞILAŞTIRILMASI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">OKSİJENLİ SOLUNUM (AEROBİK)</text>\n  <text x="35" y="88" font-size="11" fill="#581c87">• Ökaryotlarda sitoplazma + mitokondride gerçekleşir.</text>\n  <text x="35" y="110" font-size="11" fill="#581c87">• Besin monomeri CO2 ve H2O\'ya kadar tam parçalanır.</text>\n  <text x="35" y="132" font-size="11" fill="#581c87">• ETS görev yapar; son elektron alıcısı oksijendir (O2).</text>\n  <text x="35" y="154" font-size="11" fill="#581c87">• SDF ve Oksidatif fosforilasyon ile net 30-32 ATP üretilir.</text>\n  <text x="35" y="176" font-size="11" fill="#581c87">• Ortak başlangıç evresi: Sitoplazmadaki GLİKOLİZ.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">FERMANTASYON (ETİL ALKOL / LAKTİK ASİT)</text>\n  <text x="370" y="88" font-size="11" fill="#7c2d12">• Tüm evreleri sitoplazmada gerçekleşir.</text>\n  <text x="370" y="110" font-size="11" fill="#7c2d12">• Glikoz organik son ürünlere kadar kısmi parçalanır.</text>\n  <text x="370" y="132" font-size="11" fill="#7c2d12">• ETS ve oksijen kullanılmaz; son ürün devresi NADH\'ı yükseltger.</text>\n  <text x="370" y="154" font-size="11" fill="#7c2d12">• Yalnız glikolizde SDF ile net 2 ATP sentezlenir.</text>\n  <text x="370" y="176" font-size="11" fill="#7c2d12">• Çizgili kas ve olgun alyuvarda laktik asit oluşur.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Glikoliz enzimleri tüm canlılarda ortaktır; çeşitliliği son ürün evresindeki enzimler belirler.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
